211	    \ElsIf{$\mathcal{T} = \text{IV}$}
212	        \State $M \gets \text{MC-SIMEX}$ \Comment{64.7\% bias reduction}
213	    \ElsIf{$\mathcal{T} \in \{\text{Collider, M-bias}\}$}
214	        \State $M \gets \text{MC-SIMEX}$ \Comment{37.1\% / 25.7\% bias reduction}
